package tech.wenisch.smtp2x.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="smtp_credential") public class SmtpCredential { @Id private UUID id=UUID.randomUUID();@Column(nullable=false,unique=true,length=320)private String username;@Column(name="password_hash",nullable=false,length=200)private String passwordHash;@Column(nullable=false)private boolean enabled=true;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();protected SmtpCredential(){}public SmtpCredential(String u,String p){username=u;passwordHash=p;}public UUID getId(){return id;}public String getUsername(){return username;}public String getPasswordHash(){return passwordHash;}public boolean isEnabled(){return enabled;}public void enabled(boolean v){enabled=v;}public void changePassword(String p){passwordHash=p;}}
